<?php
$page_title = 'Ficha de Riesgo SGSI';
require_once __DIR__ . '/../../includes/load.php';
require_once __DIR__ . '/../../config/app.php';
require_once __DIR__ . '/funciones.php';

sgsi_ensure_schema();
require_permiso('riesgos_sgsi', 'ver');
$id = (int)($_GET['id'] ?? $_POST['IdRiesgo'] ?? 0);
$risk = $id > 0 ? sgsi_risk($id) : null;
if ($id > 0 && !$risk) { $session->msg('d','El riesgo solicitado no existe.'); redirect('index.php',false); }

if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    csrf_require();
    $action = trim((string)($_POST['action'] ?? ''));
    $userId = sgsi_user_id();
    try {
        if ($action === 'save_summary') {
            require_permiso('riesgos_sgsi', $id > 0 ? 'editar' : 'crear');
            $scenario = trim((string)($_POST['Escenario'] ?? ''));
            $process = trim((string)($_POST['Proceso'] ?? ''));
            $owner = trim((string)($_POST['DuenoRiesgo'] ?? ''));
            $status = strtoupper(trim((string)($_POST['Estado'] ?? 'IDENTIFICADO')));
            $treatment = strtoupper(trim((string)($_POST['Tratamiento'] ?? '')));
            $review = trim((string)($_POST['FechaRevision'] ?? ''));
            $notes = trim((string)($_POST['Observaciones'] ?? ''));
            $principalKey = trim((string)($_POST['ActivoPrincipal'] ?? ''));
            $relatedKeys = array_values(array_unique(array_filter(array_map('strval',(array)($_POST['ActivosRelacionados'] ?? [])))));
            $principal = sgsi_parse_asset($principalKey);
            if (!$principal) throw new RuntimeException('Seleccione un activo principal válido.');
            if (mb_strlen($scenario) < 10 || mb_strlen($scenario) > 700) throw new RuntimeException('Describa el escenario de riesgo entre 10 y 700 caracteres.');
            if ($process === '' || $owner === '') throw new RuntimeException('Proceso y dueño del riesgo son obligatorios.');
            if (!in_array($status,['IDENTIFICADO','EN_TRATAMIENTO','EN_SEGUIMIENTO','ACEPTADO','CERRADO'],true)) throw new RuntimeException('Estado de riesgo no válido.');
            if ($treatment !== '' && !in_array($treatment,['REDUCIR','ACEPTAR','TRANSFERIR','EVITAR'],true)) throw new RuntimeException('Decisión de tratamiento no válida.');
            $db->query('START TRANSACTION');
            if ($id > 0) {
                $db->query("UPDATE sgsi_riesgos SET Escenario=".sgsi_q($scenario).",Proceso=".sgsi_q($process).",DuenoRiesgo=".sgsi_q($owner).",Estado=".sgsi_q($status).",Tratamiento=".sgsi_nullable($treatment).",FechaRevision=".sgsi_date_or_null($review).",Observaciones=".sgsi_nullable($notes).",ActualizadoPor={$userId} WHERE IdRiesgo={$id}");
            } else {
                $db->query("INSERT INTO sgsi_riesgos (Escenario,Proceso,DuenoRiesgo,Estado,Tratamiento,FechaRevision,Observaciones,CreadoPor,ActualizadoPor) VALUES (".sgsi_q($scenario).','.sgsi_q($process).','.sgsi_q($owner).','.sgsi_q($status).','.sgsi_nullable($treatment).','.sgsi_date_or_null($review).','.sgsi_nullable($notes).",{$userId},{$userId})");
                $id = (int)$db->insert_id();
                $db->query("UPDATE sgsi_riesgos SET Codigo=".sgsi_q(sgsi_make_code('RSGSI',$id))." WHERE IdRiesgo={$id}");
            }
            $db->query("DELETE FROM sgsi_riesgo_activos WHERE IdRiesgo={$id}");
            $db->query("INSERT INTO sgsi_riesgo_activos (IdRiesgo,TipoActivo,IdActivo,EsPrincipal) VALUES ({$id},".sgsi_q($principal['type']).','.(int)$principal['id'].',1)');
            foreach ($relatedKeys as $key) {
                if ($key === $principalKey || !($asset = sgsi_parse_asset($key))) continue;
                $db->query("INSERT IGNORE INTO sgsi_riesgo_activos (IdRiesgo,TipoActivo,IdActivo,EsPrincipal) VALUES ({$id},".sgsi_q($asset['type']).','.(int)$asset['id'].',0)');
            }
            $db->query('COMMIT');
            $session->msg('s','Resumen del riesgo guardado correctamente.');
            sgsi_redirect_risk($id,'resumen');
        }

        if (!$risk) throw new RuntimeException('Primero guarde el resumen del riesgo.');
        require_permiso('riesgos_sgsi','editar');

        if ($action === 'link_control') {
            $controlId=(int)($_POST['IdControl']??0);
            if (!$db->fetch_assoc($db->query("SELECT IdControl FROM sgsi_controles WHERE IdControl={$controlId} LIMIT 1"))) throw new RuntimeException('Seleccione un control válido.');
            $db->query("INSERT IGNORE INTO sgsi_riesgo_controles (IdRiesgo,IdControl) VALUES ({$id},{$controlId})");
            $session->msg('s','Control vinculado al riesgo.'); sgsi_redirect_risk($id,'controles');
        }
        if ($action === 'add_control') {
            $code=strtoupper(trim((string)($_POST['Codigo']??'')));$description=trim((string)($_POST['Descripcion']??''));$responsible=trim((string)($_POST['Responsable']??''));$frequency=trim((string)($_POST['Frecuencia']??''));$state=strtoupper(trim((string)($_POST['EstadoControl']??'PENDIENTE_VALIDACION')));$evidence=trim((string)($_POST['Evidencia']??''));
            if (mb_strlen($description)<5||$responsible==='') throw new RuntimeException('Descripción y responsable del control son obligatorios.');
            if (!in_array($state,['PROPUESTO','PENDIENTE_VALIDACION','IMPLEMENTADO','EFICAZ','INEFICAZ','INACTIVO'],true)) throw new RuntimeException('Estado de control no válido.');
            if ($code!==''&&$db->fetch_assoc($db->query("SELECT IdControl FROM sgsi_controles WHERE Codigo=".sgsi_q($code)." LIMIT 1"))) throw new RuntimeException('El código del control ya existe. Puede vincular el control existente.');
            $db->query("INSERT INTO sgsi_controles (Codigo,Descripcion,Responsable,Frecuencia,Estado,Evidencia,CreadoPor) VALUES (".sgsi_q($code?:'PENDIENTE').','.sgsi_q($description).','.sgsi_q($responsible).','.sgsi_nullable($frequency).','.sgsi_q($state).','.sgsi_nullable($evidence).",{$userId})");
            $controlId=(int)$db->insert_id();if($code==='')$db->query("UPDATE sgsi_controles SET Codigo=".sgsi_q(sgsi_make_code('CTRL',$controlId))." WHERE IdControl={$controlId}");
            $db->query("INSERT INTO sgsi_riesgo_controles (IdRiesgo,IdControl) VALUES ({$id},{$controlId})");
            $session->msg('s','Control creado y vinculado.');sgsi_redirect_risk($id,'controles');
        }
        if ($action === 'update_control') {
            $controlId=(int)($_POST['IdControl']??0);$state=strtoupper(trim((string)($_POST['EstadoControl']??'')));$evidence=trim((string)($_POST['Evidencia']??''));
            $linked=$db->fetch_assoc($db->query("SELECT 1 FROM sgsi_riesgo_controles WHERE IdRiesgo={$id} AND IdControl={$controlId}"));
            if(!$linked||!in_array($state,['PROPUESTO','PENDIENTE_VALIDACION','IMPLEMENTADO','EFICAZ','INEFICAZ','INACTIVO'],true))throw new RuntimeException('Control o estado no válido.');
            $db->query("UPDATE sgsi_controles SET Estado=".sgsi_q($state).",Evidencia=".sgsi_nullable($evidence)." WHERE IdControl={$controlId}");
            $session->msg('s','Control actualizado.');sgsi_redirect_risk($id,'controles');
        }
        if ($action === 'unlink_control') {
            $controlId=(int)($_POST['IdControl']??0);$db->query("DELETE FROM sgsi_riesgo_controles WHERE IdRiesgo={$id} AND IdControl={$controlId}");
            $session->msg('s','Control desvinculado; permanece disponible en el catálogo.');sgsi_redirect_risk($id,'controles');
        }
        if ($action === 'add_plan') {
            $planAction=trim((string)($_POST['Accion']??''));$responsible=trim((string)($_POST['Responsable']??''));$date=trim((string)($_POST['FechaProgramada']??''));$state=strtoupper(trim((string)($_POST['EstadoPlan']??'PENDIENTE')));$evidence=trim((string)($_POST['Evidencia']??''));$approval=strtoupper(trim((string)($_POST['Aprobacion']??'PENDIENTE')));
            if(mb_strlen($planAction)<5||$responsible==='')throw new RuntimeException('Acción y responsable del plan son obligatorios.');
            if(!in_array($state,['PENDIENTE','EN_PROCESO','COMPLETADO','CANCELADO'],true)||!in_array($approval,['PENDIENTE','APROBADO','RECHAZADO'],true))throw new RuntimeException('Estado o aprobación del plan no válido.');
            $db->query("INSERT INTO sgsi_planes (IdRiesgo,Accion,Responsable,FechaProgramada,Estado,Evidencia,Aprobacion,CreadoPor) VALUES ({$id},".sgsi_q($planAction).','.sgsi_q($responsible).','.sgsi_date_or_null($date).','.sgsi_q($state).','.sgsi_nullable($evidence).','.sgsi_q($approval).",{$userId})");
            $planId=(int)$db->insert_id();$db->query("UPDATE sgsi_planes SET Codigo=".sgsi_q(sgsi_make_code('PLAN',$planId))." WHERE IdPlan={$planId}");
            $session->msg('s','Plan de tratamiento registrado.');sgsi_redirect_risk($id,'planes');
        }
        if ($action === 'update_plan') {
            $planId=(int)($_POST['IdPlan']??0);$state=strtoupper(trim((string)($_POST['EstadoPlan']??'')));$evidence=trim((string)($_POST['Evidencia']??''));$approval=strtoupper(trim((string)($_POST['Aprobacion']??'')));
            if(!$db->fetch_assoc($db->query("SELECT 1 FROM sgsi_planes WHERE IdPlan={$planId} AND IdRiesgo={$id}")))throw new RuntimeException('Plan no válido.');
            if(!in_array($state,['PENDIENTE','EN_PROCESO','COMPLETADO','CANCELADO'],true)||!in_array($approval,['PENDIENTE','APROBADO','RECHAZADO'],true))throw new RuntimeException('Estado o aprobación no válida.');
            $db->query("UPDATE sgsi_planes SET Estado=".sgsi_q($state).",Evidencia=".sgsi_nullable($evidence).",Aprobacion=".sgsi_q($approval)." WHERE IdPlan={$planId}");
            $session->msg('s','Seguimiento del plan actualizado.');sgsi_redirect_risk($id,'planes');
        }
        if ($action === 'generate_control') {
            $planId=(int)($_POST['IdPlan']??0);$plan=$db->fetch_assoc($db->query("SELECT * FROM sgsi_planes WHERE IdPlan={$planId} AND IdRiesgo={$id} LIMIT 1"));
            if(!$plan)throw new RuntimeException('Plan no válido.');if((int)$plan['ControlGeneradoId']>0)throw new RuntimeException('Este plan ya generó un control.');
            $db->query("INSERT INTO sgsi_controles (Codigo,Descripcion,Responsable,Frecuencia,Estado,Evidencia,OrigenPlanId,CreadoPor) VALUES ('PENDIENTE',".sgsi_q($plan['Accion']).','.sgsi_q($plan['Responsable']).",NULL,'PENDIENTE_VALIDACION',".sgsi_nullable($plan['Evidencia']).",{$planId},{$userId})");
            $controlId=(int)$db->insert_id();$db->query("UPDATE sgsi_controles SET Codigo=".sgsi_q(sgsi_make_code('CTRL',$controlId))." WHERE IdControl={$controlId}");
            $db->query("INSERT INTO sgsi_riesgo_controles (IdRiesgo,IdControl) VALUES ({$id},{$controlId})");$db->query("UPDATE sgsi_planes SET ControlGeneradoId={$controlId} WHERE IdPlan={$planId}");
            $session->msg('s','Control generado y pendiente de validación.');sgsi_redirect_risk($id,'controles');
        }
        if ($action === 'add_evaluation') {
            $type=strtoupper(trim((string)($_POST['Tipo']??'')));$date=trim((string)($_POST['FechaEvaluacion']??''));$probability=(int)($_POST['Probabilidad']??0);$impact=(int)($_POST['Impacto']??0);$evaluator=trim((string)($_POST['Evaluador']??''));$justification=trim((string)($_POST['Justificacion']??''));
            if(!in_array($type,['INHERENTE','RESIDUAL'],true)||$probability<1||$probability>5||$impact<1||$impact>5)throw new RuntimeException('Tipo, probabilidad o impacto no válidos.');
            if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date)||$evaluator===''||mb_strlen($justification)<5)throw new RuntimeException('Fecha, evaluador y justificación son obligatorios.');
            $result=sgsi_risk_level($probability,$impact);
            $db->query("INSERT INTO sgsi_evaluaciones (IdRiesgo,Tipo,FechaEvaluacion,Probabilidad,Impacto,Puntaje,Nivel,Evaluador,Justificacion,CreadoPor) VALUES ({$id},".sgsi_q($type).','.sgsi_q($date).",{$probability},{$impact},{$result['score']},".sgsi_q($result['level']).','.sgsi_q($evaluator).','.sgsi_q($justification).",{$userId})");
            $session->msg('s','Evaluación histórica registrada.');sgsi_redirect_risk($id,'evaluaciones');
        }
        if ($action === 'add_efficacy') {
            $target=trim((string)($_POST['Objetivo']??''));$date=trim((string)($_POST['FechaVerificacion']??''));$result=strtoupper(trim((string)($_POST['Resultado']??'')));$responsible=trim((string)($_POST['Responsable']??''));$evidence=trim((string)($_POST['Evidencia']??''));$observation=trim((string)($_POST['Observacion']??''));
            if(!preg_match('/^(CONTROL|PLAN):(\d+)$/',$target,$match)||!in_array($result,['EFICAZ','PARCIAL','INEFICAZ'],true))throw new RuntimeException('Objetivo o resultado de eficacia no válido.');
            $targetType=$match[1];$targetId=(int)$match[2];$valid=$targetType==='CONTROL'?$db->fetch_assoc($db->query("SELECT 1 FROM sgsi_riesgo_controles WHERE IdRiesgo={$id} AND IdControl={$targetId}")):$db->fetch_assoc($db->query("SELECT 1 FROM sgsi_planes WHERE IdRiesgo={$id} AND IdPlan={$targetId}"));
            if(!$valid||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date)||$responsible===''||$evidence==='')throw new RuntimeException('Complete fecha, responsable y evidencia de una acción vinculada.');
            $db->query("INSERT INTO sgsi_eficacias (IdRiesgo,TipoObjetivo,IdObjetivo,FechaVerificacion,Resultado,Responsable,Evidencia,Observacion,CreadoPor) VALUES ({$id},".sgsi_q($targetType).",{$targetId},".sgsi_q($date).','.sgsi_q($result).','.sgsi_q($responsible).','.sgsi_q($evidence).','.sgsi_nullable($observation).",{$userId})");
            $session->msg('s','Verificación de eficacia registrada.');sgsi_redirect_risk($id,'eficacia');
        }
        if ($action === 'add_acceptance') {
            $evaluationId=(int)($_POST['IdEvaluacion']??0);$decision=strtoupper(trim((string)($_POST['Decision']??'')));$approver=trim((string)($_POST['Aprobador']??''));$date=trim((string)($_POST['FechaDecision']??''));$justification=trim((string)($_POST['Justificacion']??''));$review=trim((string)($_POST['FechaRevision']??''));
            $evaluation=$db->fetch_assoc($db->query("SELECT * FROM sgsi_evaluaciones WHERE IdEvaluacion={$evaluationId} AND IdRiesgo={$id} AND Tipo='RESIDUAL' LIMIT 1"));
            if(!$evaluation||!in_array($decision,['APROBADO','RECHAZADO'],true)||$approver===''||mb_strlen($justification)<5||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date)||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$review))throw new RuntimeException('Complete correctamente la aceptación vinculada a una evaluación residual.');
            $db->query("INSERT INTO sgsi_aceptaciones (IdRiesgo,IdEvaluacion,Decision,Aprobador,FechaDecision,Justificacion,FechaRevision,CreadoPor) VALUES ({$id},{$evaluationId},".sgsi_q($decision).','.sgsi_q($approver).','.sgsi_q($date).','.sgsi_q($justification).','.sgsi_q($review).",{$userId})");
            if($decision==='APROBADO')$db->query("UPDATE sgsi_riesgos SET Estado='ACEPTADO',Tratamiento='ACEPTAR',FechaRevision=".sgsi_q($review).",ActualizadoPor={$userId} WHERE IdRiesgo={$id}");
            $session->msg('s','Decisión sobre el riesgo residual registrada.');sgsi_redirect_risk($id,'aceptaciones');
        }
        throw new RuntimeException('Operación no reconocida.');
    } catch (Throwable $error) {
        try { $db->query('ROLLBACK'); } catch (Throwable $ignored) {}
        $session->msg('d',$error->getMessage());
        if($id>0)sgsi_redirect_risk($id,'resumen');
        redirect('riesgo.php',false);
    }
}

$risk=$id>0?sgsi_risk($id):null;
$riskAssets=$controls=$availableControls=$plans=$evaluations=$efficacies=$acceptances=$residualEvaluations=[];
$primaryKey='';$relatedKeys=[];$assetCatalog=sgsi_asset_catalog();
if($risk){
    $riskAssets=find_by_sql("SELECT * FROM sgsi_riesgo_activos WHERE IdRiesgo={$id} ORDER BY EsPrincipal DESC,IdRelacion");
    foreach($riskAssets as $relation){$key=$relation['TipoActivo'].':'.(int)$relation['IdActivo'];if((int)$relation['EsPrincipal']===1)$primaryKey=$key;else$relatedKeys[]=$key;}
    $controls=find_by_sql("SELECT c.* FROM sgsi_riesgo_controles rc INNER JOIN sgsi_controles c ON c.IdControl=rc.IdControl WHERE rc.IdRiesgo={$id} ORDER BY c.Codigo");
    $availableControls=find_by_sql("SELECT c.* FROM sgsi_controles c WHERE NOT EXISTS (SELECT 1 FROM sgsi_riesgo_controles rc WHERE rc.IdRiesgo={$id} AND rc.IdControl=c.IdControl) ORDER BY c.Codigo");
    $plans=find_by_sql("SELECT * FROM sgsi_planes WHERE IdRiesgo={$id} ORDER BY IdPlan DESC");
    $evaluations=find_by_sql("SELECT * FROM sgsi_evaluaciones WHERE IdRiesgo={$id} ORDER BY FechaEvaluacion DESC,IdEvaluacion DESC");
    $residualEvaluations=array_values(array_filter($evaluations,fn($row)=>$row['Tipo']==='RESIDUAL'));
    $efficacies=find_by_sql("SELECT * FROM sgsi_eficacias WHERE IdRiesgo={$id} ORDER BY FechaVerificacion DESC,IdEficacia DESC");
    $acceptances=find_by_sql("SELECT a.*,e.Puntaje,e.Nivel,e.FechaEvaluacion FROM sgsi_aceptaciones a INNER JOIN sgsi_evaluaciones e ON e.IdEvaluacion=a.IdEvaluacion WHERE a.IdRiesgo={$id} ORDER BY a.FechaDecision DESC,a.IdAceptacion DESC");
}
$currentUser=sgsi_user_name();
$extraCss = [
    'https://cdn.jsdelivr.net/npm/select2@4.1.0-rc.0/dist/css/select2.min.css',
    'https://cdn.jsdelivr.net/npm/@ttskch/select2-bootstrap4-theme@1.5.2/dist/select2-bootstrap4.min.css',
];
include_once __DIR__ . '/../../layouts/header.php';
?>
