</style>
<section class="content-header pb-1"><div class="container-fluid d-flex justify-content-between align-items-center"><h1 class="h4 mb-0"><i class="fas fa-shield-alt mr-2 text-info"></i><?=$risk?sgsi_h($risk['Codigo']):'Nuevo riesgo SGSI'?></h1><div><?php if($risk):?><a href="exportar.php?id=<?=$id?>" class="btn btn-sm btn-outline-success"><i class="fas fa-file-excel mr-1"></i>Exportar fila</a><?php endif;?> <a href="index.php" class="btn btn-sm btn-outline-secondary"><i class="fas fa-arrow-left mr-1"></i>Volver</a></div></div></section>
<section class="content"><div class="container-fluid"><?=display_msg($msg)?>
 <div class="card rf-banner mb-3"><div class="card-body d-md-flex justify-content-between align-items-center"><div><div class="small text-uppercase font-weight-bold opacity-75">Ficha de trabajo del riesgo</div><h2 class="h4 font-weight-bold mb-1"><?=$risk?sgsi_h($risk['Escenario']):'Identifique el escenario y su activo principal'?></h2><div class="small"><?=$risk?sgsi_h($risk['Proceso'].' · '.$risk['DuenoRiesgo']):'La evaluación, controles y tratamiento se habilitan después de guardar el resumen.'?></div></div><?php if($risk):?><div class="text-md-right mt-3 mt-md-0"><div class="small text-uppercase opacity-75">Estado</div><strong><?=sgsi_h(str_replace('_',' ',$risk['Estado']))?></strong></div><?php endif;?></div></div>
 <ul class="nav nav-pills rf-tabs mb-3" role="tablist"><?php foreach(['resumen'=>['fa-id-card','Resumen'],'controles'=>['fa-shield','Controles'],'planes'=>['fa-list-check','Planes'],'evaluaciones'=>['fa-calculator','Evaluaciones'],'eficacia'=>['fa-circle-check','Eficacia'],'aceptaciones'=>['fa-user-check','Aceptaciones']] as $tab=>$meta):?><li class="nav-item"><a class="nav-link <?=$tab==='resumen'?'active':''?> <?=(!$risk&&$tab!=='resumen')?'disabled':''?>" data-toggle="pill" href="#tab-<?=$tab?>"><i class="fas <?=$meta[0]?> mr-1"></i><?=$meta[1]?></a></li><?php endforeach;?></ul>
